//! Test support for the AI-GEN files (`gen_*.rs`, generated by `tools/gen/ai_patterns.py`): every generated
//! port lists the exe spans it was matched against with a 64-bit FNV-1a hash (`BODIES`); the test re-reads
//! the exe and checks them, so a port can never drift from the bytes it was generated from. The exe is the
//! user's (`$SA_GTA_EXE` or `~/sa-engine/re/gta/1.0-US/gta_sa.exe`); without it the check is skipped.
#![cfg(all(test, not(sa_phase_a)))]

use std::vec::Vec;

fn exe() -> Option<Vec<u8>> {
    let path = std::env::var("SA_GTA_EXE")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|_| {
            std::path::PathBuf::from(std::env::var("HOME").unwrap_or_default())
                .join("sa-engine/re/gta/1.0-US/gta_sa.exe")
        });
    std::fs::read(path).ok()
}

/// The bytes of `n` bytes at virtual address `va` (section raw data; `None` outside every section).
fn image(exe: &[u8], va: u32, n: u32) -> Option<Vec<u8>> {
    let u16_at = |o: usize| u16::from_le_bytes([exe[o], exe[o + 1]]) as usize;
    let u32_at = |o: usize| u32::from_le_bytes(exe[o..o + 4].try_into().unwrap());
    let pe = u32_at(0x3C) as usize;
    let (nsec, opt) = (u16_at(pe + 6), u16_at(pe + 20));
    let base = u32_at(pe + 24 + 28);
    for s in 0..nsec {
        let h = pe + 24 + opt + s * 40;
        let (vsize, va0, rsize, raw) = (
            u32_at(h + 8),
            base + u32_at(h + 12),
            u32_at(h + 16),
            u32_at(h + 20),
        );
        if va >= va0 && va + n <= va0 + vsize.max(rsize) {
            return Some(
                (0..n)
                    .map(|k| {
                        let o = va + k - va0;
                        if o < rsize { exe[(raw + o) as usize] } else { 0 }
                    })
                    .collect(),
            );
        }
    }
    None
}

fn fnv(data: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in data {
        h ^= u64::from(*b);
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    h
}

/// Checks every `(addr, hash, spans)` row against the exe.
pub fn check_bodies(rows: &[crate::gen_leaves::Body]) {
    let Some(exe) = exe() else {
        std::eprintln!("note: gta_sa.exe not found, generated bodies not checked");
        return;
    };
    let mut bad = Vec::new();
    for (addr, hash, spans) in rows {
        let mut data = Vec::new();
        for (va, n) in spans.iter() {
            data.extend(
                image(&exe, *va, *n).unwrap_or_else(|| panic!("{addr:#x}: span {va:#x} not in the image")),
            );
        }
        if fnv(&data) != *hash {
            bad.push(*addr);
        }
    }
    assert!(
        bad.is_empty(),
        "generated bodies that no longer match the exe: {bad:#x?}"
    );
}
